                .andExpect(status().isUnauthorized())
                .andExpect(content().contentType(JSON_UTF8))
                .andExpect(header().string(HttpHeaders.WWW_AUTHENTICATE, "Token"))
                .andExpect(jsonPath("$.errors.token[0]").value("is missing"));
